mapper.select:
SELECT al.id record_id ,al.security_code ,al.security_short_name ,al.security_type ,si.issuer_code ,si.issuer issuer_name ,al.target_pool_id ,al.target_pool_name ,al.adjust_mode ,al.audit_time FROM ip_adjust_log al INNER JOIN dict_security_type dst ON dst.security_type = al.security_type AND dst.is_deleted = 0 AND dst.category_type IN ('bond', 'company') LEFT JOIN rrs_securityinfo si ON si.wind_code = al.security_code WHERE al.is_deleted = 0 AND al.audit_status = '20' AND al.target_pool_id IN
#{poolId}
AND al.audit_time >= #{windowStart} AND al.audit_time < #{windowEnd} AND ( dst.category_type = 'company' OR si.maturity_date IS NULL OR si.maturity_date > DATE_FORMAT(CURDATE(), '%Y%m%d') ) ORDER BY al.audit_time ASC ,al.id ASC
